document.addEventListener("DOMContentLoaded",()=>{gsap.registerPlugin(ScrollTrigger);const e=new Lenis({lerp:.1,wheelMultiplier:.7,infinite:!1,gestureOrientation:"vertical",normalizeWheel:!1,smoothTouch:!1});window.lenis=e,e.on("scroll",ScrollTrigger.update),ScrollTrigger.scrollerProxy(document.documentElement,{scrollTop(r){return arguments.length&&e.scrollTo(r,{immediate:!0}),e.scroll},scrollHeight:()=>document.documentElement.scrollHeight,getBoundingClientRect:()=>({top:0,left:0,width:window.innerWidth,height:window.innerHeight})}),ScrollTrigger.addEventListener("refresh",()=>e.resize?.()),gsap.ticker.add(r=>{e.raf(1e3*r)}),gsap.ticker.lagSmoothing(0),ScrollTrigger.refresh()});